// CSD_RATIONALE_BEGIN
// The 52% best (attempt 43) fails mainly on semantic mismatch: the model picks
// wrong table/column identifiers even when the parser accepts the SQL.
// RegenerateUnitOnGroundingFailure is purpose-built for this: it generates SQL
// unit-by-unit, detecting any completed symbol whose identifier tokens are not
// grounded in the prompt (schema), and rolling back + resampling with a penalty
// until a grounded completion is found or the retry budget is exhausted.
//
// Strategy:
// Phase 1: ≤5 unconstrained preamble steps (detect natural "<<" entry).
// Phase 2: Force-open constrained span with OpenConstrainedSpan if not yet inside.
// Phase 3: Call RegenerateUnitOnGroundingFailure from the empty constrained prefix
//   (currentConstrainedOut=[]) with most of the step budget, maxRetries=3,
//   maxRollbackBudget=30.  At entry the constrained prefix is always [], so the
//   helper generates a fresh SQL query with grounded identifiers.
// Phase 4: Close if complete, or CloseSpanWithinBudget(≤80) as fallback.
//
// Key differences from attempt 43 (52% best):
// - Phase 3 uses RegenerateUnitOnGroundingFailure instead of GroupBoostedConstrainedStep,
//   directly targeting the schema-grounding gap that caused 141 syntax-valid-wrong
//   answers in the best result.
// - No CountTokenOccurrences / SafeBoostedConstrainedStep (which caused regression).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1: insideConstrainedOut flips true only when RenderedEndsWith fires;
//     we set currentConstrainedOut := [], valid by precondition parser.IsValidPrefix([]).
//     On EOS, insideConstrainedOut stays false; implication is vacuous.
//
//   Phase 2 (OpenConstrainedSpan): only reached when !insideConstrainedOut.
//     Helper sets currentConstrainedOut := []; valid by precondition.
//
//   Phase 3 (RegenerateUnitOnGroundingFailure): the API postcondition guarantees
//     resultConstrained is always parser-valid. We set currentConstrainedOut :=
//     resultConstrained, so IsValidPrefix(currentConstrainedOut) holds.
//     insideConstrainedOut remains true (span not closed yet).
//
//   Phase 4a (CloseConstrainedSpan): sets insideConstrainedOut := false, making
//     the implication vacuously true; currentConstrainedOut := [].
//   Phase 4b (CloseSpanWithinBudget): postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut); invariant preserved.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 1: each UnconstrainedStep increments steps by 1 and appends at most 1
//     token (0 on EOS). |generated| grows by at most 1 per +1 steps. ✓
//
//   Phase 2 (OpenConstrainedSpan): steps += 1; |generated| grows by exactly 1
//     ("<<"). 1:1 ratio preserved. ✓
//
//   Phase 3: At entry, currentConstrainedOut = [], so generated = stablePrefix.
//     After: generated := generated_old + resultConstrained; steps += budget.
//     API cost bound guarantees |resultConstrained| <= budget.
//     So |generated_new| = |generated_old| + |resultConstrained|
//       <= (|generatedPrefix| + steps_old) + budget
//       = |generatedPrefix| + steps_new. ✓
//
//   Phase 4a (CloseConstrainedSpan): steps += 1; |generated| grows by at most 1
//     (">>"). 1:1. ✓
//   Phase 4b (CloseSpanWithinBudget): |generatedOut| <= |generated| + closeBudget;
//     steps += closeBudget. Invariant preserved. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate SQL: <<query>> using ONLY exact table and column names from the schema. Always include a FROM clause with the correct table name. Use proper JOIN ... ON conditions when combining tables. Add WHERE, GROUP BY, HAVING, ORDER BY, LIMIT as required by the question. Output only valid SQL between << and >>.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) for "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL generation via RegenerateUnitOnGroundingFailure
// At this point currentConstrainedOut = [] (fresh span just opened)
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var budget: nat;
  if remaining > 10 {
    budget := remaining - 5;
  } else if remaining > 0 {
    budget := remaining;
  } else {
    budget := 0;
  }
  if budget > 0 {
    var constrainedPrompt := prompt + generated;
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, budget, 3, 30
    );
    // resultConstrained is parser-valid (API postcondition)
    // |resultConstrained| <= budget (cost bound: each step generates at most 1 token)
    generated := generated + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + budget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining4 := maxSteps - steps;
    var closeBudget: nat;
    if remaining4 <= 80 {
      closeBudget := remaining4;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

